<template><AccountLayout bare><main class="po-page" :aria-busy="busy">
<header class="po-header"><div class="po-heading"><FileBadge :size="30"/><div><h1>Credit Notes</h1><p>Seller Credit Notes</p></div></div><div v-if="view==='list'" class="po-header-search"><Search/><input v-model="filters.search" placeholder="Search credit note, PO, invoice or seller..."></div><div class="po-actions"><button v-if="view==='list'" class="po-btn primary" @click="startNew"><Plus/> New Credit Note</button><button v-else class="po-btn" @click="back"><ArrowLeft/> Back to list</button></div></header>
<div v-if="error" class="po-alert error">{{ error }}</div><div v-if="notice" class="po-alert success">{{ notice }}</div>
<template v-if="view==='list'"><form class="po-filters" @submit.prevent="page=1"><label>Date Range<span class="po-date-range"><input v-model="filters.from" type="date"><input v-model="filters.to" type="date"></span></label><label>Seller<select v-model="filters.seller"><option value="">All Sellers</option><option v-for="x in sellers" :key="x">{{ x }}</option></select></label><label>Status<select v-model="filters.status"><option value="">All Status</option><option v-for="x in statuses" :key="x">{{ x }}</option></select></label><button class="po-btn primary"><Search/> Filter</button><button class="po-btn" type="button" @click="filters=initialFilters()"><RotateCcw/> Reset</button></form><section class="po-list"><header class="po-section-head"><h2>Credit Notes List <small>Showing {{ filtered.length }} Credit Notes</small></h2><div class="po-actions"><select v-model.number="perPage"><option :value="15">15 entries</option><option :value="30">30 entries</option></select><button class="po-btn green" @click="exportExcel"><Download/> Export</button></div></header><div class="po-table-scroll"><table class="po-list-table"><thead><tr><th>No.</th><th>Credit Note No.</th><th>PO No.</th><th>Vendor / Company Name</th><th>Credit Note Date</th><th>Grand Total</th><th>Status</th><th>Created By</th><th>Created Date</th><th>Action</th></tr></thead><tbody><tr v-for="(row,index) in paginated" :key="row.id"><td>{{ (page-1)*perPage+index+1 }}</td><td><button class="po-link" @click="openNote(row)">{{ row.credit_note_no }}</button></td><td>{{ source(row).po_no }}</td><td>{{ source(row).seller_name }}</td><td>{{ dateLabel(row.credit_note_date) }}</td><td class="po-number">{{ money(row.total) }} {{ source(row).currency_code }}</td><td><span class="po-pill" :class="slug(row.status)">{{ row.status }}</span></td><td>{{ row.creator?.name||'-' }}</td><td>{{ dateTimeLabel(row.created_at) }}</td><td><div class="po-actions"><button class="po-icon" title="View" @click="openNote(row)"><Eye/></button><button class="po-icon" title="Print" @click="openAndPrint(row)"><Printer/></button><button class="po-icon" title="Email" @click="emailRow(row)"><Mail/></button></div></td></tr><tr v-if="!paginated.length"><td colspan="10" class="po-empty">No credit notes found.</td></tr></tbody></table></div><footer class="po-pagination"><span>Showing {{ filtered.length?(page-1)*perPage+1:0 }} to {{ Math.min(page*perPage,filtered.length) }} of {{ filtered.length }}</span><div class="po-actions"><button class="po-icon" :disabled="page===1" @click="page--"><ChevronLeft/></button><b>{{ page }} / {{ pages }}</b><button class="po-icon" :disabled="page===pages" @click="page++"><ChevronRight/></button></div></footer><div class="po-action-bar"><button class="po-btn primary" @click="startNew"><Plus/> New</button><button class="po-btn green" @click="exportExcel"><FileSpreadsheet/> Export</button><button class="po-btn" @click="printPage"><Printer/> Print</button><button class="po-btn" @click="savePdf"><FileDown/> Save PDF</button></div></section></template>
<div v-else class="po-workspace"><section class="po-document"><header class="po-document-head"><div class="po-heading"><FileBadge/><h2>Credit Note</h2></div><div class="po-actions"><b>{{ form.credit_note_no||'New credit note' }}</b><span class="po-pill" :class="slug(form.status)">{{ form.status }}</span><button class="po-icon" @click="printPage"><Printer/></button><button class="po-icon" @click="emailNote"><Mail/></button></div></header><div class="po-document-body"><div class="po-details-grid"><section><h3>Sellers</h3><Field label="Vendor ID" :model-value="invoice.seller_no"/><Field label="Company Name" :model-value="invoice.seller_name"/><Field v-for="x in sellerFields" :key="x.key" :label="x.label" :model-value="invoice.seller_details?.[x.key]" :multiline="x.key==='address'"/></section><section><h3>Requested By</h3><Field label="Department" :model-value="invoice.department"/><Field label="Contact Person" :model-value="invoice.requested_by"/><Field v-for="x in requesterFields" :key="x.key" :label="x.label" :model-value="invoice.requester_details?.[x.key]" :multiline="x.key==='address'"/><Field label="Project" :model-value="invoice.project"/></section><section><h3>Credit Note Details</h3><div v-if="editing" class="po-field"><label>Related Invoice</label><i>:</i><select v-model="form.purchase_invoice_id" @change="applyInvoice"><option :value="null" disabled>Select invoice</option><option v-for="x in invoices" :key="x.id" :value="x.id">{{ x.invoice_no }} - {{ x.seller_name }}</option></select></div><Field v-else label="Related Invoice No." :model-value="invoice.invoice_no"/><Field label="Credit Note No." v-model="form.credit_note_no" :editable="editing"/><Field label="PO No." :model-value="invoice.po_no"/><Field label="Credit Note Date" v-model="form.credit_note_date" :editable="editing" type="date" :display-value="dateLabel(form.credit_note_date)"/><Field label="Due Date" v-model="form.due_date" :editable="editing" type="date" :display-value="dateLabel(form.due_date)"/><Field label="Delivery Location" :model-value="invoice.delivery_location"/><Field label="Currency" :model-value="invoice.currency_code"/><Field label="Status" :model-value="form.status"/><Field label="Payment Term" :model-value="invoice.payment_term"/><Field label="Payment Method" :model-value="invoice.payment_method"/></section></div>
<section class="po-items"><div v-if="editing" class="po-section-head"><h3>Credit Items / Services</h3><button class="po-btn compact primary" @click="addItem"><Plus/> Add line</button></div><div class="po-table-scroll"><table><thead><tr><th>Item / Service</th><th>Item Code / SKU</th><th>UOM</th><th>Qty</th><th>Credit Rate</th><th>Sub Total</th><th>Sales Tax</th><th>Total</th><th v-if="editing"></th></tr></thead><tbody><tr v-for="(item,index) in form.items" :key="index"><td><input v-if="editing" v-model="item.name"><span v-else>{{ item.name }}</span></td><td><input v-if="editing" v-model="item.code"><span v-else>{{ item.code||'-' }}</span></td><td><input v-if="editing" v-model="item.uom"><span v-else>{{ item.uom }}</span></td><td><input v-if="editing" v-model.number="item.quantity" type="number" min=".01" step=".01"><span v-else>{{ money(item.quantity) }}</span></td><td><input v-if="editing" v-model.number="item.cost_rate" type="number" min="0" step=".01"><span v-else>{{ money(item.cost_rate) }}</span></td><td>{{ money(lineSubtotal(item)) }}</td><td><input v-if="editing" v-model.number="item.sales_tax" type="number" min="0" step=".01"><span v-else>{{ money(item.sales_tax) }}</span></td><td>{{ money(lineTotal(item)) }}</td><td v-if="editing"><button class="po-icon danger" @click="form.items.splice(index,1)"><Trash2/></button></td></tr><tr v-if="!form.items.length"><td :colspan="editing?9:8" class="po-empty">No credit lines added.</td></tr></tbody><tfoot><tr><th colspan="5">Total</th><th>{{ money(subtotal) }}</th><th>{{ money(tax) }}</th><th>{{ money(total) }}</th><th v-if="editing"></th></tr></tfoot></table></div></section>
<div class="po-bottom-grid"><section><h3>Terms &amp; Condition</h3><textarea v-if="editing" v-model="form.terms" rows="4"/><p v-else class="po-terms">{{ form.terms||'-' }}</p><Field label="Reason" v-model="form.reason" :editable="editing" :options="reasons"/><Field label="Created By" :model-value="form.creator?.name"/><Field label="Created Date" :model-value="dateTimeLabel(form.created_at)"/></section><section><h3>Delivery Information</h3><Field label="Delivery Location" :model-value="invoice.delivery_location"/><Field label="Delivery Contact" :model-value="invoice.delivery_details?.contact_person"/><Field label="Delivery Phone" :model-value="invoice.delivery_details?.phone"/><Field label="Delivery Instructions" :model-value="invoice.notes" multiline/></section><section class="po-totals"><Field label="Sub Total" :model-value="money(subtotal)"/><Field label="Sales Tax (Total)" :model-value="money(tax)"/><div><span>Grand Total ({{ invoice.currency_code||'CAD' }})</span><strong>{{ money(total) }}</strong></div></section></div><section v-if="form.attachments.length" class="po-attachments"><h3>Attachments</h3><button v-for="file in form.attachments" :key="file.id" class="po-btn compact" @click="downloadAttachment(file)"><Paperclip/> {{ file.name }}</button></section></div>
<footer class="po-document-footer"><div class="po-actions"><button class="po-btn" @click="startNew"><Plus/> New</button><button class="po-btn" :disabled="editing||form.status==='Approved'" @click="editing=true"><Pencil/> Edit</button><button class="po-btn danger" :disabled="!form.id||form.status==='Approved'" @click="deleteNote"><Trash2/> Delete</button><button class="po-btn primary" :disabled="!editing" @click="saveNote"><Save/> Save</button><button v-if="editing" class="po-btn" @click="cancel"><X/> Cancel</button><button class="po-btn" @click="savePdf"><FileDown/> Save PDF</button><button class="po-btn" @click="printPage"><Printer/> Print</button><button class="po-btn" @click="emailNote"><Mail/> Email</button><button class="po-btn green" :disabled="!canDecide" @click="workflow('approve')"><Check/> Approve</button><button class="po-btn danger" :disabled="!canDecide" @click="workflow('reject')"><X/> Reject</button></div><div class="po-actions"><button class="po-btn" :disabled="!form.id" @click="fileInput.click()"><Paperclip/> Attach File</button><input ref="fileInput" class="po-hidden" type="file" @change="upload"><button class="po-btn" :disabled="!form.id" @click="modal='audit'"><History/> Audit Log</button><button class="po-btn" :disabled="!canSubmit" @click="workflow('submit')"><Send/> Send for Approval</button><button class="po-btn green" @click="exportExcel"><FileSpreadsheet/> Export Excel</button></div></footer></section>
<aside class="po-sidebar"><section><h3>Transaction Tracker</h3><div class="po-table-scroll"><table class="po-tracker"><thead><tr><th>Doc. Type</th><th>No.</th><th>Date</th><th>Total</th></tr></thead><tbody><tr><td>Purchase Order</td><td>{{ invoice.po_no||'-' }}</td><td>{{ dateLabel(invoice.purchase_order?.po_date) }}</td><td>{{ money(invoice.total) }}</td></tr><tr><td>Purchase Invoice</td><td>{{ invoice.invoice_no||'-' }}</td><td>{{ dateLabel(invoice.invoice_date) }}</td><td>{{ money(invoice.total) }}</td></tr><tr><td>Credit Note</td><td>{{ form.credit_note_no||'-' }}</td><td>{{ dateLabel(form.credit_note_date) }}</td><td>-{{ money(total) }}</td></tr></tbody><tfoot><tr><th>Balance</th><th colspan="2">{{ invoice.currency_code }}</th><th>{{ money(Math.max(0,Number(invoice.total||0)-total)) }}</th></tr></tfoot></table></div></section><section><h3>Current Credit Note Details</h3><Field label="Credit Note No." :model-value="form.credit_note_no"/><Field label="PO No." :model-value="invoice.po_no"/><Field label="Related Invoice No." :model-value="invoice.invoice_no"/><Field label="Credit Note Date" :model-value="dateLabel(form.credit_note_date)"/><Field label="Due Date" :model-value="dateLabel(form.due_date)"/><Field label="Currency" :model-value="invoice.currency_code"/><Field label="Status" :model-value="form.status"/><Field label="Payment Term" :model-value="invoice.payment_term"/></section></aside></div>
<div v-if="modal" class="po-modal-backdrop" @click.self="modal=''"> <section class="po-modal"><header><h2>Credit Note Audit Log</h2><button class="po-icon" @click="modal=''"><X/></button></header><table><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody><tr v-for="x in form.activities" :key="x.id"><td>{{ dateTimeLabel(x.created_at) }}</td><td>{{ x.actor }}</td><td>{{ x.action }}</td><td>{{ details(x.changes) }}</td></tr></tbody></table></section></div>
</main></AccountLayout></template>
<script setup>
import{computed,onMounted,ref,watch}from'vue';import{FileBadge,Search,Plus,ArrowLeft,RotateCcw,Download,Eye,Printer,Mail,ChevronLeft,ChevronRight,FileSpreadsheet,FileDown,Trash2,Pencil,Save,X,Check,Paperclip,History,Send}from'lucide-vue-next';import AccountLayout from'../components/AccountLayout.vue';import Field from'../components/PurchaseOrderField.vue';import client from'../api/client';import{roundMoney,lineSubtotal,lineTotal,today,money,dateLabel,dateTimeLabel}from'../utils/purchaseOrders'
const rows=ref([]),invoices=ref([]),view=ref('list'),form=ref({}),editing=ref(false),busy=ref(false),error=ref(''),notice=ref(''),modal=ref(''),fileInput=ref(null),page=ref(1),perPage=ref(15),statuses=['Draft','Pending','Approved','Rejected'],reasons=['Material Return','Price Adjustment','Damaged Goods','Overpayment','Service Credit','Other'],sellerFields=[{key:'contact_person',label:'Contact Person'},{key:'phone',label:'Phone'},{key:'email',label:'Email'},{key:'address',label:'Address'},{key:'website',label:'Website'},{key:'tax_number',label:'Tax Number'},{key:'vendor_category',label:'Vendor Category'}],requesterFields=[{key:'phone',label:'Phone'},{key:'email',label:'Email'},{key:'company_name',label:'Company Name'},{key:'address',label:'Address'}];const initialFilters=()=>({search:'',from:'',to:'',seller:'',status:''}),filters=ref(initialFilters()),blank=()=>({id:null,credit_note_no:'',purchase_invoice_id:null,credit_note_date:today(),due_date:today(),status:'Draft',reason:'',items:[],terms:'This credit note is issued for the amount mentioned above.',notes:'',activities:[],attachments:[],purchase_invoice:null})
const source=x=>x.purchase_invoice||{},invoice=computed(()=>source(form.value)),slug=x=>String(x||'').toLowerCase().replace(/\s+/g,'-'),sellers=computed(()=>[...new Set(rows.value.map(x=>source(x).seller_name).filter(Boolean))].sort()),filtered=computed(()=>rows.value.filter(x=>{const f=filters.value,i=source(x),q=f.search.toLowerCase(),d=String(x.credit_note_date).slice(0,10);return(!q||[x.credit_note_no,i.po_no,i.invoice_no,i.seller_name].some(v=>String(v||'').toLowerCase().includes(q)))&&(!f.seller||i.seller_name===f.seller)&&(!f.status||x.status===f.status)&&(!f.from||d>=f.from)&&(!f.to||d<=f.to)})),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/perPage.value))),paginated=computed(()=>filtered.value.slice((page.value-1)*perPage.value,page.value*perPage.value)),subtotal=computed(()=>roundMoney((form.value.items||[]).reduce((s,x)=>s+lineSubtotal(x),0))),tax=computed(()=>roundMoney((form.value.items||[]).reduce((s,x)=>s+Number(x.sales_tax||0),0))),total=computed(()=>roundMoney(subtotal.value+tax.value)),canSubmit=computed(()=>form.value.id&&!editing.value&&form.value.status==='Draft'),canDecide=computed(()=>form.value.id&&!editing.value&&['Draft','Pending'].includes(form.value.status));const apiError=e=>Object.values(e.response?.data?.errors||{})[0]?.[0]||e.response?.data?.message||e.message
async function all(url){let p=1,last=1,out=[];do{const{data}=await client.get(url,{params:{per_page:100,page:p}}),b=data.data;out.push(...(b?.data||b||[]));last=b?.last_page||1;p++}while(p<=last);return out}async function load(){[rows.value,invoices.value]=await Promise.all([all('/seller-credit-notes'),all('/purchase-invoices')])}function normalize(x){const b=blank();return{...b,...x,purchase_invoice_id:x.purchase_invoice_id?Number(x.purchase_invoice_id):null,credit_note_date:String(x.credit_note_date||today()).slice(0,10),due_date:String(x.due_date||today()).slice(0,10),items:(x.items||[]).map(i=>({...i})),activities:x.activities||[],attachments:x.attachments||[]}}function startNew(){form.value=blank();editing.value=true;view.value='detail'}async function openNote(x){busy.value=true;try{const{data}=await client.get('/seller-credit-notes/'+x.id);form.value=normalize(data.data);editing.value=false;view.value='detail'}catch(e){error.value=apiError(e)}finally{busy.value=false}}function back(){view.value='list';editing.value=false}async function cancel(){form.value.id?await openNote(form.value):back()}function applyInvoice(){const i=invoices.value.find(x=>x.id===Number(form.value.purchase_invoice_id));if(i){form.value.purchase_invoice=i;form.value.due_date=String(i.due_date||today()).slice(0,10)}}function addItem(){const x=invoice.value.items?.[0]||{};form.value.items.push({invoice_item_index:0,name:'',code:x.code||'',uom:'LS',quantity:1,cost_rate:0,sales_tax:0})}
async function saveNote(){if(!form.value.purchase_invoice_id||!form.value.reason||!form.value.items.length){error.value='Select an invoice, reason, and add a credit line.';return}try{const{data}=form.value.id?await client.put('/seller-credit-notes/'+form.value.id,form.value):await client.post('/seller-credit-notes',form.value);form.value=normalize(data.data);editing.value=false;await load();notice.value='Seller credit note saved.'}catch(e){error.value=apiError(e)}}async function workflow(action){try{const{data}=await client.post('/seller-credit-notes/'+form.value.id+'/workflow',{action});form.value=normalize(data.data);await load();notice.value='Credit note '+form.value.status.toLowerCase()+'.'}catch(e){error.value=apiError(e)}}async function deleteNote(){if(!confirm('Delete '+form.value.credit_note_no+'?'))return;try{await client.delete('/seller-credit-notes/'+form.value.id);await load();back()}catch(e){error.value=apiError(e)}}async function upload(e){const f=e.target.files[0];if(!f)return;const b=new FormData();b.append('file',f);try{const{data}=await client.post('/seller-credit-notes/'+form.value.id+'/attachments',b);form.value=normalize(data.data)}catch(x){error.value=apiError(x)}finally{e.target.value=''}}async function downloadAttachment(f){const{data}=await client.get('/seller-credit-notes/'+form.value.id+'/attachments/'+f.id,{responseType:'blob'});downloadBlob(data,f.name)}function downloadBlob(b,n){const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function details(v){try{return Object.entries(typeof v==='string'?JSON.parse(v):v||{}).map(([k,x])=>k+': '+x).join(', ')}catch{return''}}
function printPage(){window.print()}async function openAndPrint(x){await openNote(x);setTimeout(printPage,50)}function emailRow(x){const i=source(x);window.location.href='mailto:'+encodeURIComponent(i.seller_details?.email||'')+'?subject='+encodeURIComponent('Credit Note '+x.credit_note_no)}function emailNote(){emailRow(form.value)}async function exportExcel(){const{default:ExcelJS}=await import('exceljs'),b=new ExcelJS.Workbook(),s=b.addWorksheet('Credit Notes');s.addRow(['Credit Note','PO','Invoice','Seller','Date','Total','Status','Created By']);filtered.value.forEach(x=>{const i=source(x);s.addRow([x.credit_note_no,i.po_no,i.invoice_no,i.seller_name,dateLabel(x.credit_note_date),Number(x.total),x.status,x.creator?.name])});s.columns.forEach(x=>x.width=22);downloadBlob(new Blob([await b.xlsx.writeBuffer()]),'seller-credit-notes.xlsx')}async function savePdf(){const{default:jsPDF}=await import('jspdf'),p=new jsPDF();p.setFontSize(18);p.text(view.value==='list'?'Credit Notes List':'Credit Note '+form.value.credit_note_no,15,18);p.setFontSize(10);let y=30;(view.value==='list'?filtered.value:form.value.items).forEach(x=>{p.text(view.value==='list'?[x.credit_note_no,source(x).seller_name,money(x.total),x.status].join(' | '):[x.name,x.quantity,money(lineTotal(x))].join(' | '),15,y);y+=7});p.save('seller-credit-notes.pdf')}watch([filters,perPage],()=>page.value=1,{deep:true});watch(pages,x=>page.value=Math.min(page.value,x));onMounted(async()=>{busy.value=true;try{await load()}catch(e){error.value=apiError(e)}finally{busy.value=false}})
</script><style src="../assets/purchase-orders.css"></style>
